function connectionBanner(){
 const missing=backendStatus.insurance===404?' The running backend is missing the insurance AI routes.':backendStatus.insurance===401&&!cloudUser?' Sign in to use insurance AI.':'';
 return backendStatus.health===null?'Checking backend connection…':online?'Backend reachable.'+missing+' A connection does not verify AI availability.':'The healthcare API is temporarily unavailable. Please try again shortly.';
}
function updateConnection(){document.querySelectorAll('.backend-banner').forEach(el=>{el.textContent=connectionBanner();el.classList.toggle('offline',!online||backendStatus.insurance===404);});}
function preservePreviews(){const original=main.querySelector('[data-source-preview]');if(original){original.remove();main.replaceChildren();return original;}const preview=document.createElement('details');preview.className='design-preview live-panel';preview.innerHTML='<summary>Explore design examples · Not your data</summary><p class="live-note">These original design interactions use illustrative records. They are separate from your account and backend results.</p>';const examples=document.createElement('div');examples.className='design-examples';while(main.firstChild)examples.append(main.firstChild);preview.append(examples);return preview;}
function mountConnected(page){
 clearTimeout(insuranceRefreshTimer);if(page==='account'){renderAccount();return;}
 if(!cloudUser&&!user){
  main.innerHTML='<section class="signin-gate"><span class="material-symbols-outlined" aria-hidden="true">lock</span><h1>Sign in to continue</h1><p>Log in to access '+e(titles[page].toLowerCase())+' and your ClearCare workspace.</p>'+button('Sign in','page-signin')+'</section>';
  main.querySelector('#page-signin').onclick=()=>auth();
  return;
 }
 if(main.querySelector('#live-page-content'))return;
 const preview=preservePreviews();
 preview.querySelector('summary')?.setAttribute('title','For demo purposes only');
 const shell=document.createElement('div');shell.className='live-shell';shell.innerHTML='<div class="backend-banner" role="status"></div><section class="live-panel live-intro" id="live-page-heading"><div class="live-label">Your ClearCare workspace</div><h1>'+e(titles[page])+'</h1><p>'+e({overview:'Your saved records and plan analysis, with no assumed savings or coverage.',bill:'Enter your own bill details below to get a review of that bill. Results appear only after you run the checks.',care:'Search sourced records from the backend. Demonstration listings are hidden unless you request them.',prescriptions:'Live prescription pricing is not connected yet. Your medication costs have not been calculated.'}[page])+'</p></section><div id="live-page-content"></div>';
 if(page==='overview'||page==='bill'||page==='care')shell.querySelector('#live-page-heading')?.remove();
 if(page==='care')shell.querySelector('.backend-banner')?.remove();
 main.append(shell);main.append(preview);
 if(page==='bill')billEditor();
 if(page==='care')careSearch();
 if(page==='prescriptions')document.querySelector('#live-page-content').innerHTML='<section class="live-panel"><h2>Prescription tools</h2><p>No medication records or live pharmacy prices are available from the current backend. The design examples below remain available to explore.</p></section>';
 if(page==='overview')renderOverview();updateConnection();
}
async function renderOverview(){const target=document.querySelector('#live-page-content');if(activePage!=='overview'||!target||(!cloudUser&&!user))return;
 target.innerHTML=`<div class="overview-stats"><article class="overview-stat"><div class="stat-heading"><span>Total healthcare savings</span><span class="stat-icon material-symbols-outlined" aria-hidden="true">savings</span></div><div class="stat-value">—</div><p>No confirmed savings yet</p><div class="stat-foot">Savings appear after a bill adjustment or prescription saving is confirmed.</div></article><article class="overview-stat"><div class="stat-heading"><span>Bill audits</span><span class="stat-icon amber material-symbols-outlined" aria-hidden="true">receipt_long</span></div><div class="stat-value" id="overview-audit-count">—</div><p>Saved bill reviews</p><button class="stat-foot stat-link" id="overview-bill">Review a bill <span aria-hidden="true">↗</span></button></article><article class="overview-stat"><div class="stat-heading"><span>Rx spend</span><span class="stat-icon material-symbols-outlined" aria-hidden="true">medication</span></div><div class="stat-value">—<small> / month</small></div><p>No prescription spending recorded</p><button class="stat-foot stat-link" id="overview-rx">Explore prescription savings <span aria-hidden="true">↗</span></button></article></div><div class="overview-lower"><section class="overview-activity"><div class="overview-section-heading"><div><span class="live-label">Your workspace</span><h2>Recent activity</h2></div><span class="material-symbols-outlined" aria-hidden="true">history</span></div><div id="overview-records" aria-live="polite"><div class="activity-empty"><span class="material-symbols-outlined" aria-hidden="true">receipt_long</span><h3>No activity yet</h3><p>Your saved bill reviews will appear here.</p>${button('Review your first bill','overview-first-bill')}</div></div></section><section class="overview-estimator"><div class="overview-section-heading"><div><span class="live-label">Plan ahead</span><h2>Care cost estimator</h2></div><span class="material-symbols-outlined" aria-hidden="true">calculate</span></div><p>Look up published prices before your next visit.</p><form id="overview-estimate"><label>Service or care needed<input name="q" placeholder="MRI knee, blood test, office visit" required maxlength="150"></label><label>City<input name="city" value="${e(user?.city||'')}" placeholder="Enter a city" required maxlength="100"></label><label>Price type<select name="price_type"><option value="discounted_cash">Cash price</option><option value="payer_negotiated">Negotiated price</option><option value="gross_charge">Listed charge</option></select></label><button class="primary-action">Find an estimate <span aria-hidden="true">→</span></button></form><div id="overview-estimate-result" role="status"></div><p class="estimator-note">Published prices are not your final out-of-pocket cost. Confirm coverage and fees with the provider.</p></section></div>`;
 target.querySelector('#overview-bill').onclick=()=>route('bill');target.querySelector('#overview-first-bill').onclick=()=>route('bill');target.querySelector('#overview-rx').onclick=()=>route('prescriptions');
 target.querySelector('#overview-estimate').onsubmit=async event=>{event.preventDefault();const form=event.target,output=target.querySelector('#overview-estimate-result'),submit=form.querySelector('button');submit.disabled=true;output.textContent='Looking up prices…';await attempt(async()=>{const query=new URLSearchParams(Object.fromEntries(new FormData(form)));const data=await api.request('/prices/compare?'+query);if(!output.isConnected)return;const prices=(data.results||[]).filter(row=>!priceView(row).isDemo).map(row=>priceView(row).price).filter(price=>price!==null);const money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(value);output.textContent=prices.length?money(Math.min(...prices))+(Math.min(...prices)!==Math.max(...prices)?' – '+money(Math.max(...prices)):'')+' · '+prices.length+' published '+(prices.length===1?'price':'prices'):'No published prices found for this search.';},output);submit.disabled=false;};
 if(!user)return;const owner=user.id,records=target.querySelector('#overview-records');
 try{const data=await api.request('/reviews');if(!records.isConnected||owner!==user?.id)return;const saved=data.results||[];target.querySelector('#overview-audit-count').textContent=String(saved.length);if(saved.length)records.innerHTML=saved.slice(0,6).map(r=>`<article class="activity-item"><span class="activity-icon material-symbols-outlined" aria-hidden="true">task_alt</span><div><h3>${e(r.title)}</h3><p>Bill review saved</p></div><time datetime="${e(r.created)}">${e(new Date(r.created).toLocaleDateString(undefined,{month:'short',day:'numeric'}))}</time></article>`).join('');}catch(error){if(records.isConnected)records.innerHTML='<p class="live-error">'+e(error.message)+'</p>';}
}
window.addEventListener('clearcare:page',event=>mountConnected(event.detail.page));
refreshIdentity();if(activePage)mountConnected(activePage);
async function initialize(){
 const probe=async path=>{try{return {status:200,data:await api.request(path)};}catch(error){return {status:error.status||0};}};
 const health=await probe('/health');online=health.status===200;backendStatus.health=health.status;
 const insurance=await probe('/profile/insurance');backendStatus.insurance=insurance.status;
 try{await cloudAuth.initialize();}catch{}
 refreshIdentity();updateConnection();if(activePage==='account')renderAccount();if(activePage==='overview')renderOverview();
}
initialize();
